(293657,32629,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alerte budget : la poussette de luxe ... à 5000 euros.'::text,'est'::text,'sont'::text,'être'::text,'Alerte budget : la poussette de luxe est à 5000 euros.'::text),
(293660,32629,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe uyarısı: şatafatlı bebek arabası 5000 euro ...'::text,''::text,NULL::text,'olmak'::text,'Bütçe uyarısı: şatafatlı bebek arabası 5000 euro.'::text),
(293661,32629,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetési riasztás: a puccos babakocsi ... 5000 euró.'::text,''::text,NULL::text,'lenni'::text,'Költségvetési riasztás: a puccos babakocsi 5000 euró.'::text),
(293691,32633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie läuft normalerweise schnell, aber gerade ... sie einen schicken Kinderwagen an.'::text,'starrt'::text,'starrt'::text,NULL::text,'Sie läuft normalerweise schnell, aber gerade starrt sie einen schicken Kinderwagen an.'::text),
(293695,32633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона зазвичай ходить швидко, але саме зараз ... на розкішну коляску.'::text,'витріщається'::text,'витріщається'::text,NULL::text,'Вона зазвичай ходить швидко, але саме зараз витріщається на розкішну коляску.'::text),
(293694,32633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella suele caminar rápido, pero ahora mismo ... un carrito de lujo.'::text,'está mirando fijamente'::text,'mira fijamente'::text,NULL::text,'Ella suele caminar rápido, pero ahora mismo está mirando fijamente un carrito de lujo.'::text),
(293693,32633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude elle marche vite, mais là, elle ... une poussette de luxe.'::text,'est en train de fixer'::text,'fixe'::text,NULL::text,'D''habitude elle marche vite, mais là, elle est en train de fixer une poussette de luxe.'::text),
(293696,32633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O genelde hızlı yürür ama şu an şatafatlı bir bebek arabasına ...'::text,'dik dik bakıyor'::text,'dik dik bakar'::text,NULL::text,'O genelde hızlı yürür ama şu an şatafatlı bir bebek arabasına dik dik bakıyor.'::text),
(293697,32633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő általában gyorsan jár, de most épp egy puccos babakocsit ...'::text,'bámul'::text,'bámul'::text,NULL::text,'Ő általában gyorsan jár, de most épp egy puccos babakocsit bámul.'::text),
(300090,33344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Nilpferd ... zum Atmen auftauchen, weil es Luft braucht.'::text,'muss'::text,'muss'::text,'sollte'::text,'Das Nilpferd muss zum Atmen auftauchen, weil es Luft braucht.'::text),
(300094,33344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бегемот ... виринати за повітрям, бо йому потрібне повітря.'::text,'має'::text,'мусить'::text,'мав би'::text,'Бегемот має виринати за повітрям, бо йому потрібне повітря.'::text),
(300093,33344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hipopótamo ... salir a respirar porque necesita aire.'::text,'tiene que'::text,'debe'::text,'debería'::text,'El hipopótamo tiene que salir a respirar porque necesita aire.'::text),
(300092,33344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hippopotame ... remonter pour respirer parce qu''il a besoin d''air.'::text,'doit'::text,'doit'::text,'devrait'::text,'L''hippopotame doit remonter pour respirer parce qu''il a besoin d''air.'::text),
(300095,33344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su aygırı hava almak için yüzeye ... çünkü havaya ihtiyacı var.'::text,'çıkmak zorunda'::text,'çıkmalı'::text,'çıkmalı'::text,'Su aygırı hava almak için yüzeye çıkmak zorunda çünkü havaya ihtiyacı var.'::text),
(300096,33344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vízilónak ... feljönnie levegőért, mert levegőre van szüksége.'::text,'kell'::text,'kell'::text,'kellene'::text,'A vízilónak kell feljönnie levegőért, mert levegőre van szüksége.'::text),
(316668,35186,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, deine Herz-Sonnenbrille ... albern, aber du bist so cool.'::text,'ist'::text,'ist'::text,'bin'::text,'Ehrlich, deine Herz-Sonnenbrille ist albern, aber du bist so cool.'::text),
(316672,35186,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твої окуляри-сердечка ... кумедні, але ти такий крутий.'::text,'є'::text,'є'::text,'є'::text,'Чесно, твої окуляри-сердечка є кумедні, але ти такий крутий.'::text),
(316671,35186,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tus gafas de corazón ... ridículas, pero tú eres muy guay.'::text,'son'::text,'es'::text,'soy'::text,'Sinceramente, tus gafas de corazón son ridículas, pero tú eres muy guay.'::text),
(316670,35186,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tes lunettes cœur ... ridicules, mais tu es trop cool.'::text,'sont'::text,'est'::text,'suis'::text,'Franchement, tes lunettes cœur sont ridicules, mais tu es trop cool.'::text),
(316673,35186,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası kalpli güneş gözlüklerin saçma ... ama sen çok havalısın.'::text,''::text,NULL::text,NULL::text,'Açıkçası kalpli güneş gözlüklerin saçma ama sen çok havalısın.'::text),
(316674,35186,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a szívecskés napszemüveged ... bolondos, de te nagyon menő vagy.'::text,''::text,NULL::text,'vagyok'::text,'Őszintén, a szívecskés napszemüveged bolondos, de te nagyon menő vagy.'::text),
(316713,35191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makelloser Geschmack: Er sieht die alberne Brille und sagt: „Ich ... sie kaufen!“'::text,'werde'::text,'werde'::text,NULL::text,'Makelloser Geschmack: Er sieht die alberne Brille und sagt: „Ich werde sie kaufen!“'::text),
(316717,35191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний смак: він бачить кумедні окуляри й каже: «Я ... їх!»'::text,'куплю'::text,'збираюся купити'::text,NULL::text,'Бездоганний смак: він бачить кумедні окуляри й каже: «Я куплю їх!»'::text),
(316716,35191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gusto impecable: él ve las gafas ridículas y dice: «¡Yo ... las compraré!»'::text,''::text,'voy a'::text,NULL::text,'Gusto impecable: él ve las gafas ridículas y dice: «¡Yo las compraré!»'::text),
(316715,35191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Goût impeccable : il voit les lunettes ridicules et dit : « Je ... les achèterai ! »'::text,''::text,'vais'::text,NULL::text,'Goût impeccable : il voit les lunettes ridicules et dit : « Je les achèterai ! »'::text),
(316718,35191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz zevk: o, saçma gözlüğü görüyor ve “Onları ...!” diyor.'::text,'alacağım'::text,'alacağım'::text,NULL::text,'Kusursuz zevk: o, saçma gözlüğü görüyor ve “Onları alacağım!” diyor.'::text),
(316719,35191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan ízlés: ő meglátja a bolondos szemüveget, és azt mondja: „Meg ... venni!”'::text,'fogom'::text,'fogom'::text,NULL::text,'Hibátlan ízlés: ő meglátja a bolondos szemüveget, és azt mondja: „Meg fogom venni!”'::text),
(315192,35022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seinen Becher immer auf diesen wackeligen Tisch! Ein Albtraum!'::text,'stellt'::text,'stellend'::text,'stellte'::text,'Er stellt seinen Becher immer auf diesen wackeligen Tisch! Ein Albtraum!'::text),
(315196,35022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він завжди ... свій кухоль на цей хиткий столик! Жах!'::text,'ставить'::text,'ставлячи'::text,'поставив'::text,'Він завжди ставить свій кухоль на цей хиткий столик! Жах!'::text),
(315195,35022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él siempre ... su taza en esta mesa coja! ¡Una pesadilla!'::text,'pone'::text,'poniendo'::text,'puso'::text,'¡Él siempre pone su taza en esta mesa coja! ¡Una pesadilla!'::text),
(315194,35022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... toujours son mug sur cette table bancale ! Un cauchemar !'::text,'pose'::text,'posant'::text,'a posé'::text,'Il pose toujours son mug sur cette table bancale ! Un cauchemar !'::text),
(315197,35022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kupasını hep bu sallanan masaya ...! Tam bir kâbus!'::text,'koyar'::text,'koyarak'::text,'koydu'::text,'O, kupasını hep bu sallanan masaya koyar! Tam bir kâbus!'::text),
(315198,35022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő mindig erre a billegő asztalra ... a bögréjét! Rémálom!'::text,'teszi'::text,'tevő'::text,'tette'::text,'Ő mindig erre a billegő asztalra teszi a bögréjét! Rémálom!'::text),
(315228,35026,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du deckst normalerweise einen Teller, aber gestern ... du ein ganzes Festmahl vor. Stilvoll!'::text,'bereitetest'::text,'bereitest'::text,NULL::text,'Du deckst normalerweise einen Teller, aber gestern bereitetest du ein ganzes Festmahl vor. Stilvoll!'::text),
(315232,35026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зазвичай ставиш одну тарілку, але вчора ти ... бенкет. Стильно!'::text,'приготував'::text,'готуєш'::text,NULL::text,'Ти зазвичай ставиш одну тарілку, але вчора ти приготував бенкет. Стильно!'::text),
(315231,35026,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú normalmente pones un solo plato, pero ayer ... un banquete. ¡Qué clase!'::text,'preparaste'::text,'preparas'::text,NULL::text,'Tú normalmente pones un solo plato, pero ayer preparaste un banquete. ¡Qué clase!'::text),
(315230,35026,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu mets une seule assiette, mais hier tu ... un festin. La classe !'::text,'as préparé'::text,'prépares'::text,NULL::text,'D''habitude tu mets une seule assiette, mais hier tu as préparé un festin. La classe !'::text),
(315233,35026,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen genelde tek tabak koyarsın ama dün koca bir ziyafet ..., çok klas!'::text,'hazırladın'::text,'hazırlarsın'::text,NULL::text,'Sen genelde tek tabak koyarsın ama dün koca bir ziyafet hazırladın, çok klas!'::text),
(315234,35026,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te általában egy tányért teszel ki, de tegnap ... egy egész lakomát. Elegáns!'::text,'készítettél'::text,'készítesz'::text,NULL::text,'Te általában egy tányért teszel ki, de tegnap készítettél egy egész lakomát. Elegáns!'::text),
(328701,36523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Jugendlichen schreien alle! ... Stimmen sind so laut! Chaos!'::text,'Ihre'::text,'Seine'::text,'Seine'::text,'Die Jugendlichen schreien alle! Ihre Stimmen sind so laut! Chaos!'::text),
(328705,36523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Юнаки всі кричать! ... голоси такі гучні! Хаос!'::text,'Їхні'::text,'Його'::text,'Його'::text,'Юнаки всі кричать! Їхні голоси такі гучні! Хаос!'::text),
(328704,36523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los chavales gritan todos! ¡... voces son tan fuertes! ¡Caos!'::text,'Sus'::text,'Sus'::text,'Sus'::text,'¡Los chavales gritan todos! ¡Sus voces son tan fuertes! ¡Caos!'::text),
(328703,36523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les jeunes crient tous ! ... voix sont si fortes ! Le chaos !'::text,'Leurs'::text,'Ses'::text,'Ses'::text,'Les jeunes crient tous ! Leurs voix sont si fortes ! Le chaos !'::text),
(328706,36523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gençlerin hepsi bağırıyor! ... sesleri çok yüksek! Kaos!'::text,'Onların'::text,'Onun'::text,'Onun'::text,'Gençlerin hepsi bağırıyor! Onların sesleri çok yüksek! Kaos!'::text),
(328707,36523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalok mind kiabálnak! A ... olyan hangos! Káosz!'::text,'hangjuk'::text,'hangja'::text,'hangja'::text,'A fiatalok mind kiabálnak! A hangjuk olyan hangos! Káosz!'::text),
(328728,36526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Moment, ich hab gehört, die Jugendlichen haben so viel ... im Park gemacht.'::text,'Lärm'::text,'Lärm'::text,'einen Lärm'::text,'Moment, ich hab gehört, die Jugendlichen haben so viel Lärm im Park gemacht.'::text),
(328732,36526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп, я чула, що юнаки наробили стільки ... в парку.'::text,'шуму'::text,'шумів'::text,'шуму'::text,'Стоп, я чула, що юнаки наробили стільки шуму в парку.'::text),
(328731,36526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, yo he oído que los chavales hicieron tanto ... en el parque.'::text,'ruido'::text,'ruido'::text,'un ruido'::text,'Espera, yo he oído que los chavales hicieron tanto ruido en el parque.'::text),
(328730,36526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, j''ai entendu dire que les jeunes ont fait tellement de ... dans le parc.'::text,'bruit'::text,'bruit'::text,'un bruit'::text,'Attends, j''ai entendu dire que les jeunes ont fait tellement de bruit dans le parc.'::text),
(328733,36526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dakika, ben gençlerin parkta çok fazla ... yaptığını duydum.'::text,'gürültü'::text,'gürültüler'::text,'bir gürültü'::text,'Bir dakika, ben gençlerin parkta çok fazla gürültü yaptığını duydum.'::text),
(328734,36526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, én úgy hallottam, a fiatalok olyan nagy ... csaptak a parkban.'::text,'zajt'::text,'zajt'::text,'egy zajt'::text,'Várj, én úgy hallottam, a fiatalok olyan nagy zajt csaptak a parkban.'::text),
(310008,34446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Schauspieler lieben ... Stück über einen Wald.'::text,'ihr'::text,'sie'::text,'ihres'::text,'Die Schauspieler lieben ihr Stück über einen Wald.'::text),
(310012,34446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Актори люблять ... п''єсу про ліс.'::text,'свою'::text,'вони'::text,'їхню'::text,'Актори люблять свою п''єсу про ліс.'::text),
(310011,34446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los actores adoran ... obra sobre un bosque.'::text,'su'::text,'ellos'::text,'la suya'::text,'Los actores adoran su obra sobre un bosque.'::text),
(310010,34446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les acteurs adorent ... pièce sur une forêt.'::text,'leur'::text,'ils'::text,'la leur'::text,'Les acteurs adorent leur pièce sur une forêt.'::text),
(310013,34446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncular bir orman hakkındaki ... oyunlarını çok seviyor.'::text,'onların'::text,'onlar'::text,'onlarınki'::text,'Oyuncular bir orman hakkındaki onların oyunlarını çok seviyor.'::text),
(310014,34446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A színészek imádják egy erdőről szóló ...'::text,'darabjukat'::text,'ők'::text,'az övékét'::text,'A színészek imádják egy erdőről szóló darabjukat.'::text),
(307353,34151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, zwei ... in einem kleinen Saal sind keine Oper, Bro.'::text,'Männer'::text,'Männer'::text,'Mann'::text,'Nee, zwei Männer in einem kleinen Saal sind keine Oper, Bro.'::text),
(307357,34151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, двоє ... в маленькій залі — це не опера, бро.'::text,'чоловіків'::text,'чоловіків'::text,'чоловік'::text,'Не, двоє чоловіків в маленькій залі — це не опера, бро.'::text),
(307356,34151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, dos ... en una sala pequeña no son una ópera, tío.'::text,'hombres'::text,'hombres'::text,'hombre'::text,'Qué va, dos hombres en una sala pequeña no son una ópera, tío.'::text),
(307355,34151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, deux ... dans une petite salle, c''est pas un opéra, frère.'::text,'hommes'::text,'hommes'::text,'homme'::text,'Nan, deux hommes dans une petite salle, c''est pas un opéra, frère.'::text),
(307358,34151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok ya, küçük bir salonda iki ... opera değil, kanka.'::text,'adam'::text,'adamlar'::text,'adam'::text,'Yok ya, küçük bir salonda iki adam opera değil, kanka.'::text),
(307359,34151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ugyan, két ... egy kis teremben még nem opera, tesó.'::text,'férfi'::text,'férfi'::text,'férfi'::text,'Ugyan, két férfi egy kis teremben még nem opera, tesó.'::text),
(327954,36440,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir gesagt: „Ich ... aufhören zu grübeln und jetzt schreiben!“'::text,'werde'::text,'werde'::text,NULL::text,'Hör zu, sie hat mir gesagt: „Ich werde aufhören zu grübeln und jetzt schreiben!“'::text),
(327958,36440,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона мені сказала: «Я ... гадати й зараз почну писати!»'::text,'перестану'::text,'збираюся перестати'::text,NULL::text,'Слухай, вона мені сказала: «Я перестану гадати й зараз почну писати!»'::text),
(327957,36440,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ella me dijo: «¡Yo ... dejaré de darle vueltas y me pondré a escribir ya!»'::text,''::text,'voy a'::text,NULL::text,'Oye, ella me dijo: «¡Yo dejaré de darle vueltas y me pondré a escribir ya!»'::text),
(327956,36440,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit : « Je ... arrêterai de me poser des questions et j''écrirai maintenant ! »'::text,''::text,'vais'::text,NULL::text,'Écoute, elle m''a dit : « Je arrêterai de me poser des questions et j''écrirai maintenant ! »'::text),
(327959,36440,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o bana “Merak etmeyi ... ve şimdi yazacağım!” dedi.'::text,'bırakacağım'::text,'bırakacağım'::text,NULL::text,'Dinle, o bana “Merak etmeyi bırakacağım ve şimdi yazacağım!” dedi.'::text),
(327960,36440,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ő azt mondta nekem: „Abba ... hagyni a töprengést, és most írok!”'::text,'fogom'::text,'fogom'::text,NULL::text,'Figyu, ő azt mondta nekem: „Abba fogom hagyni a töprengést, és most írok!”'::text),
(323094,35900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du checkst ... Uhrzeit auf deiner Uhr wie ein Profi.'::text,'die'::text,'eine'::text,'eine'::text,'Ehrlich, du checkst die Uhrzeit auf deiner Uhr wie ein Profi.'::text),
(323098,35900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти перевіряєш ... час на годиннику як профі.'::text,''::text,NULL::text,NULL::text,'Чесно, ти перевіряєш час на годиннику як профі.'::text),
(323097,35900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tú miras ... hora en tu reloj como un pro.'::text,'la'::text,'una'::text,'una'::text,'La verdad, tú miras la hora en tu reloj como un pro.'::text),
