(323132,35904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''a pas ... temps avant le train.'::text,'beaucoup de'::text,'beaucoup de'::text,'du'::text,'Elle n''a pas beaucoup de temps avant le train.'::text),
(323135,35904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, trenden önce ... zamana sahip değil.'::text,'çok'::text,'çok'::text,'biraz'::text,'O, trenden önce çok zamana sahip değil.'::text),
(323136,35904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki nincs ... ideje a vonat előtt.'::text,'sok'::text,'sok'::text,'némi'::text,'Neki nincs sok ideje a vonat előtt.'::text),
(297381,33043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gierig? Nein, du ... einfach eine Toast-Legende.'::text,'bist'::text,'ist'::text,'bin'::text,'Gierig? Nein, du bist einfach eine Toast-Legende.'::text),
(297385,33043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жадібний? Ні, ти ... просто легенда тостів.'::text,'є'::text,'є'::text,'є'::text,'Жадібний? Ні, ти є просто легенда тостів.'::text),
(297384,33043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Avaricioso? No, tú ... simplemente una leyenda de las tostadas.'::text,'eres'::text,'es'::text,'soy'::text,'¿Avaricioso? No, tú eres simplemente una leyenda de las tostadas.'::text),
