(297386,33043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açgözlü mü? Hayır, sen sadece bir tost efsanesi ...'::text,''::text,NULL::text,NULL::text,'Açgözlü mü? Hayır, sen sadece bir tost efsanesi.'::text),
(297387,33043,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapzsi? Nem, te csak egy pirítóslegenda ...'::text,'vagy'::text,NULL::text,'vagyok'::text,'Kapzsi? Nem, te csak egy pirítóslegenda vagy.'::text),
(297390,33044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich nicht gierig: Er ... nur zwanzig Scheiben Toast.'::text,'machte'::text,'machte'::text,'machend'::text,'Natürlich nicht gierig: Er machte nur zwanzig Scheiben Toast.'::text),
(297394,33044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, не жадібний: він ... лише двадцять тостів.'::text,'зробив'::text,'зробив'::text,'роблячи'::text,'Звісно, не жадібний: він зробив лише двадцять тостів.'::text),
(297393,33044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No es avaricioso, claro: él ... solo veinte tostadas.'::text,'hizo'::text,'hizo'::text,'haciendo'::text,'No es avaricioso, claro: él hizo solo veinte tostadas.'::text),
(297392,33044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas avide du tout, bien sûr : il ... juste vingt tranches de pain grillé.'::text,'a fait'::text,'a fait'::text,'faisant'::text,'Pas avide du tout, bien sûr : il a fait juste vingt tranches de pain grillé.'::text),
(297395,33044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açgözlü değil tabii: o sadece yirmi dilim tost ...'::text,'yaptı'::text,'yaptı'::text,'yaparak'::text,'Açgözlü değil tabii: o sadece yirmi dilim tost yaptı.'::text),
(297396,33044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze, nem kapzsi: ő csak húsz szelet pirítóst ...'::text,'készített'::text,'készített'::text,'készítő'::text,'Persze, nem kapzsi: ő csak húsz szelet pirítóst készített.'::text),
(323184,35910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat ... an einem Fuß.'::text,'5 Zehen'::text,'5 Zeh'::text,'5 Zehen'::text,'Sie hat 5 Zehen an einem Fuß.'::text),
(323188,35910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона має ... на одній нозі.'::text,'5 пальців'::text,'5 палець'::text,'5 пальців'::text,'Вона має 5 пальців на одній нозі.'::text),
(323187,35910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella tiene ... en un pie.'::text,'5 dedos'::text,'5 dedo'::text,'5 dedos'::text,'Ella tiene 5 dedos en un pie.'::text),
(323186,35910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a ... à un pied.'::text,'5 orteils'::text,'5 orteil'::text,'5 orteils'::text,'Elle a 5 orteils à un pied.'::text),
(323189,35910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun bir ayağında ... var.'::text,'5 parmak'::text,'5 parmak'::text,'5 parmaklar'::text,'Onun bir ayağında 5 parmak var.'::text),
(323190,35910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki az egyik lábán ... van.'::text,'5 lábujja'::text,'5 lábujja'::text,'5 lábujja'::text,'Neki az egyik lábán 5 lábujja van.'::text),
(323202,35912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekter Strandtag, klar: so viel heißer ... und eine Muschel unter ihren Zehen.'::text,'Sand'::text,'Sand'::text,'ein Sand'::text,'Perfekter Strandtag, klar: so viel heißer Sand und eine Muschel unter ihren Zehen.'::text),
(323206,35912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ідеальний пляжний день, звісно: стільки гарячого ... і мушля під її пальцями.'::text,'піску'::text,'пісків'::text,'піску'::text,'Ідеальний пляжний день, звісно: стільки гарячого піску і мушля під її пальцями.'::text),
(323205,35912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Día de playa perfecto, obvio: tanta ... caliente y una concha bajo sus dedos.'::text,'arena'::text,'arena'::text,'una arena'::text,'Día de playa perfecto, obvio: tanta arena caliente y una concha bajo sus dedos.'::text),
(323204,35912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Journée plage parfaite, évidemment : tellement de ... chaud et un coquillage sous ses orteils.'::text,'sable'::text,'sable'::text,'un sable'::text,'Journée plage parfaite, évidemment : tellement de sable chaud et un coquillage sous ses orteils.'::text),
(323207,35912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mükemmel plaj günü tabii: bir sürü sıcak ... ve ayak parmaklarının altında bir deniz kabuğu.'::text,'kum'::text,'kumlar'::text,'bir kum'::text,'Mükemmel plaj günü tabii: bir sürü sıcak kum ve ayak parmaklarının altında bir deniz kabuğu.'::text),
