(323400,35934,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hinter der Tür ist eine Toilette. Alle wollen auf ... Toilette.'::text,'die'::text,'eine'::text,'eine'::text,'Hinter der Tür ist eine Toilette. Alle wollen auf die Toilette.'::text),
(323404,35934,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'За дверима туалет. Усі хочуть до ... туалету.'::text,''::text,NULL::text,NULL::text,'За дверима туалет. Усі хочуть до туалету.'::text),
(323403,35934,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Detrás de la puerta hay un baño. Todos quieren usar ... baño.'::text,'el'::text,'un'::text,'un'::text,'Detrás de la puerta hay un baño. Todos quieren usar el baño.'::text),
(323402,35934,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Derrière la porte, il y a des toilettes. Tout le monde veut utiliser ... toilettes.'::text,'les'::text,'des'::text,'des'::text,'Derrière la porte, il y a des toilettes. Tout le monde veut utiliser les toilettes.'::text),
(323405,35934,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapının arkasında bir tuvalet var. Herkes ... tuvalete gitmek istiyor.'::text,''::text,'bir'::text,'bir'::text,'Kapının arkasında bir tuvalet var. Herkes tuvalete gitmek istiyor.'::text),
(323406,35934,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ajtó mögött egy vécé van. Mindenki ... vécére akar menni.'::text,'a'::text,'egy'::text,'egy'::text,'Az ajtó mögött egy vécé van. Mindenki a vécére akar menni.'::text),
(323463,35941,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hasst normalerweise Schlangen, aber gestern Abend ... du auf die Toilette. Respekt.'::text,'wartetest'::text,'wartest'::text,NULL::text,'Du hasst normalerweise Schlangen, aber gestern Abend wartetest du auf die Toilette. Respekt.'::text),
(323467,35941,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зазвичай ненавидиш черги, але вчора ввечері ... своєї черги в туалет. Респект.'::text,'чекала'::text,'чекаєш'::text,NULL::text,'Ти зазвичай ненавидиш черги, але вчора ввечері чекала своєї черги в туалет. Респект.'::text),
(323466,35941,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú normalmente odias las colas, pero anoche ... para ir al baño. Respeto.'::text,'esperaste'::text,'esperas'::text,NULL::text,'Tú normalmente odias las colas, pero anoche esperaste para ir al baño. Respeto.'::text),
(323465,35941,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu détestes les files, mais hier soir tu ... pour les toilettes. Respect.'::text,'as attendu'::text,'attends'::text,NULL::text,'D''habitude tu détestes les files, mais hier soir tu as attendu pour les toilettes. Respect.'::text),
(323468,35941,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen genelde kuyruklardan nefret edersin ama dün akşam tuvalet için ..., helal olsun.'::text,'bekledin'::text,'beklersin'::text,NULL::text,'Sen genelde kuyruklardan nefret edersin ama dün akşam tuvalet için bekledin, helal olsun.'::text),
(323469,35941,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te általában utálod a sorokat, de tegnap este ... a vécére. Respekt.'::text,'vártál'::text,'vársz'::text,NULL::text,'Te általában utálod a sorokat, de tegnap este vártál a vécére. Respekt.'::text),
(302295,33589,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie nimmt ... Schraubenzieher aus dem Werkzeugkoffer.'::text,'einen'::text,'ersten'::text,'einmal'::text,'Sie nimmt einen Schraubenzieher aus dem Werkzeugkoffer.'::text),
(302299,33589,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона дістає з набору ... викрутку.'::text,'одну'::text,'першу'::text,'один раз'::text,'Вона дістає з набору одну викрутку.'::text),
(302298,33589,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella saca ... destornillador del maletín.'::text,'un'::text,'primer'::text,'una vez'::text,'Ella saca un destornillador del maletín.'::text),
(302297,33589,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle sort ... tournevis de la mallette.'::text,'un'::text,'premier'::text,'une fois'::text,'Elle sort un tournevis de la mallette.'::text),
(302300,33589,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, setten ... tornavida çıkarıyor.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'O, setten bir tornavida çıkarıyor.'::text),
(302301,33589,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő kivesz ... csavarhúzót a készletből.'::text,'egy'::text,'első'::text,'egyszer'::text,'Ő kivesz egy csavarhúzót a készletből.'::text),
(302322,33592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fünfzig Werkzeuge in einem Koffer, genau was wir brauchten: noch mehr ...'::text,'Ausrüstung.'::text,'Ausrüstung.'::text,'eine Ausrüstung.'::text,'Fünfzig Werkzeuge in einem Koffer, genau was wir brauchten: noch mehr Ausrüstung.'::text),
(302326,33592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'П''ятдесят інструментів в одному наборі, саме те, чого ми потребували: ще більше ...'::text,'спорядження.'::text,'спорядження.'::text,'спорядження.'::text,'П''ятдесят інструментів в одному наборі, саме те, чого ми потребували: ще більше спорядження.'::text),
(302325,33592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cincuenta herramientas en un maletín, justo lo que nosotros necesitábamos: más ...'::text,'equipo.'::text,'equipo.'::text,'un equipo.'::text,'Cincuenta herramientas en un maletín, justo lo que nosotros necesitábamos: más equipo.'::text),
(302324,33592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cinquante outils dans une mallette, exactement ce qu''il nous fallait : encore plus de ...'::text,'matériel.'::text,'matériel.'::text,'un matériel.'::text,'Cinquante outils dans une mallette, exactement ce qu''il nous fallait : encore plus de matériel.'::text),
(302327,33592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir sette elli alet, tam da bizim ihtiyacımız olan şey: daha fazla ...'::text,'ekipman.'::text,'ekipmanlar.'::text,'bir ekipman.'::text,'Tek bir sette elli alet, tam da bizim ihtiyacımız olan şey: daha fazla ekipman.'::text),
(302328,33592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ötven szerszám egy készletben, pont erre volt szükségünk: még több ...'::text,'felszerelés.'::text,'felszerelés.'::text,'egy felszerelés.'::text,'Ötven szerszám egy készletben, pont erre volt szükségünk: még több felszerelés.'::text),
(323526,35948,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi, klar: Der Zahnarzt braucht sehr wenig ... für ihre Zähne.'::text,'Zeit'::text,'Zeit'::text,'eine Zeit'::text,'Ein echter Profi, klar: Der Zahnarzt braucht sehr wenig Zeit für ihre Zähne.'::text),
(323530,35948,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній професіонал, звісно: стоматолог потребує дуже мало ... на її зуби.'::text,'часу'::text,'часу'::text,'часу'::text,'Справжній професіонал, звісно: стоматолог потребує дуже мало часу на її зуби.'::text),
(323529,35948,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un auténtico profesional, obvio: el dentista necesita muy poco ... para sus dientes.'::text,'tiempo'::text,'tiempo'::text,'un tiempo'::text,'Un auténtico profesional, obvio: el dentista necesita muy poco tiempo para sus dientes.'::text),
(323528,35948,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro, évidemment : le dentiste a besoin de très peu de ... pour ses dents.'::text,'temps'::text,'temps'::text,'un temps'::text,'Un vrai pro, évidemment : le dentiste a besoin de très peu de temps pour ses dents.'::text),
(323531,35948,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir profesyonel tabii: diş hekiminin onun dişleri için çok az ... ihtiyacı var.'::text,'zamana'::text,'zamanlara'::text,'bir zamana'::text,'Gerçek bir profesyonel tabii: diş hekiminin onun dişleri için çok az zamana ihtiyacı var.'::text),
(323532,35948,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi, persze: a fogorvosnak nagyon kevés ... kell a fogaihoz.'::text,'idő'::text,'idő'::text,'egy idő'::text,'Igazi profi, persze: a fogorvosnak nagyon kevés idő kell a fogaihoz.'::text),
(323580,35954,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich die Zähne mit der grünen Zahnbürste putzen.'::text,'kann'::text,'kann'::text,'kann'::text,'Er kann sich die Zähne mit der grünen Zahnbürste putzen.'::text),
(323584,35954,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... чистити зуби зеленою зубною щіткою.'::text,'може'::text,'може'::text,'може'::text,'Він може чистити зуби зеленою зубною щіткою.'::text),
(323583,35954,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... lavarse los dientes con el cepillo verde.'::text,'puede'::text,'puede'::text,'puede'::text,'Él puede lavarse los dientes con el cepillo verde.'::text),
(323582,35954,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... se brosser les dents avec la brosse à dents verte.'::text,'peut'::text,'peut'::text,'peut'::text,'Il peut se brosser les dents avec la brosse à dents verte.'::text),
(323585,35954,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, dişlerini yeşil diş fırçasıyla ...'::text,'fırçalayabilir'::text,'fırçalayabilir'::text,'fırçalayabilir'::text,'O, dişlerini yeşil diş fırçasıyla fırçalayabilir.'::text),
(323586,35954,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő meg ... mosni a fogát a zöld fogkefével.'::text,'tudja'::text,'tudja'::text,'tudja'::text,'Ő meg tudja mosni a fogát a zöld fogkefével.'::text),
(323607,35957,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, Hausregel: Jeder ... seine eigene Zahnbürste benutzen, ohne Witz.'::text,'muss'::text,'muss'::text,'sollte'::text,'Bro, Hausregel: Jeder muss seine eigene Zahnbürste benutzen, ohne Witz.'::text),
