(308734,34304,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він п''є так ...! Один гучний ковток зруйнує це спокійне озеро!'::text,'тихо'::text,'тихий'::text,'тиша'::text,'Він п''є так тихо! Один гучний ковток зруйнує це спокійне озеро!'::text),
(308733,34304,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él bebe tan ...! ¡Un sorbo ruidoso destruirá este lago tranquilo!'::text,'silenciosamente'::text,'silencioso'::text,'silencio'::text,'¡Él bebe tan silenciosamente! ¡Un sorbo ruidoso destruirá este lago tranquilo!'::text),
(308732,34304,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il boit si ... ! Une gorgée bruyante détruira ce lac paisible !'::text,'silencieusement'::text,'silencieux'::text,'silence'::text,'Il boit si silencieusement ! Une gorgée bruyante détruira ce lac paisible !'::text),
(308735,34304,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çok ... içiyor! Tek bir gürültülü yudum bu huzurlu gölü mahvedecek!'::text,'sessizce'::text,'sessiz'::text,'sessizlik'::text,'O çok sessizce içiyor! Tek bir gürültülü yudum bu huzurlu gölü mahvedecek!'::text),
