(308856,34318,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er muss vor ... Ende des Tages die Erlaubnis kriegen.'::text,'dem'::text,'einem'::text,'einem'::text,'Bro, er muss vor dem Ende des Tages die Erlaubnis kriegen.'::text),
